package set_body

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "set_body"
	command.Identifiers = []string{"set-body"}
	command.Category = "Server System"
	command.Help = "Rewrite the body keys of a route.yaml"
	command.LongDescription = "Overwrites the body keys of one route.yaml: how the body is read, whether it is required, the longest one accepted and the content-type the dispatch demands. Empty options leave the current value alone. Declaring a json-schema is add-body-field's job; --drop-schema deletes the one already declared."
	command.Examples = []string{"set-body create-user --type json --required --max-bytes 2097152", "set-body upload-avatar --type raw --content-type application/octet-stream", "set-body ping --type none"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "how the body is read: none, raw, text, json or form (application/x-www-form-urlencoded, read into a map[string][]string)",
			Examples:    []string{"set-body create-user --type json"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--type"},
		},
		{
			Id:          "required",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "answer 400 when the body is absent or empty",
			Examples:    []string{"set-body create-user --required"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--required"},
		},
		{
			Id:          "optional",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "accept an absent body again",
			Examples:    []string{"set-body create-user --optional"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--optional"},
		},
		{
			Id:          "max-bytes",
			Type:        "int",
			Required:    false,
			Array:       false,
			Description: "the longest body accepted, in bytes; a longer one is answered 413",
			Examples:    []string{"set-body create-user --max-bytes 2097152"},
			Default:     "-1",
			HasDefault:  true,
			Identifiers: []string{"--max-bytes"},
		},
		{
			Id:          "content-type",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the only content-type accepted; a divergent one is answered 415",
			Examples:    []string{"set-body create-user --content-type text/plain"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--content-type"},
		},
		{
			Id:          "drop-schema",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "delete the declared json-schema, leaving the body unvalidated",
			Examples:    []string{"set-body create-user --drop-schema"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--drop-schema"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"set-body create-user --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "route",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the route to edit (identifier or package name)",
			Examples:    []string{"set-body create-user --type json"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
